from pathlib import Path
import json,hashlib,html
B=Path(__file__).resolve().parent.parent;D=B.parent
U=json.loads((D/'UX_CONTRACT.json').read_text());DIR=json.loads((D/'DIRECTION_SET.json').read_text())
assert U['gate']=='PASS' and DIR['selected_direction']=='A' and U['selected_direction']['approval_evidence']==DIR['selection_evidence']
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
bindings={'ux_contract_sha256':sha(D/'UX_CONTRACT.json'),'direction_set_sha256':sha(D/'DIRECTION_SET.json'),'selected_direction':'A','ux_contract_version':U['ux_contract_version'],'direction_version':DIR['direction_version']}
policy={k:v['approved_value'] for k,v in U['required_product_policy'].items()}
contract={k:U[k] for k in ['screens','states']};contract['interactions']=[{k:i[k] for k in ['interaction_id','screen_id','trigger','destinations','failure_destination_states']} for i in U['interactions']]
sections=''.join(f'<section class="screen" data-screen-id="{s["screen_id"]}" hidden aria-label="{html.escape(s["name"])}"></section>' for s in U['screens'])
states=''.join(f'<template id="state-{s["state_id"]}"><div data-state-id="{s["state_id"]}">{html.escape(s["visible_feedback"])}</div></template>' for s in U['states'])
controls=''.join(f'<template id="control-{i["interaction_id"]}"><button type="button" data-interaction-id="{i["interaction_id"]}">{html.escape(i["trigger"])}</button></template>' for i in U['interactions'])
css=(B/'implementation/style.css').read_text();domain=(B/'implementation/domain.js').read_text();ui=(B/'implementation/ui.js').read_text()
approved_matrix=policy['six_level_parameters_and_test_cadence']['training_matrix']
js='const APPROVED_MATRIX='+json.dumps(approved_matrix,ensure_ascii=False)+';\n'+'const POLICY='+json.dumps(policy,ensure_ascii=False)+';\nconst CONTRACT='+json.dumps(contract,ensure_ascii=False)+';\nconst BINDINGS='+json.dumps(bindings,ensure_ascii=False)+';\n'+domain+'\n'+ui
head='<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="color-scheme" content="light"><link rel="icon" href="data:,"><title>随身语音教练｜Human 2 交互模拟器</title><style>'+css+'</style></head><body>'
body='<main class="workspace"><div class="device"><div class="statusbar"><span>9:41</span><span>◉　▰</span></div><div class="app-label">产品交互演示 · 记录仅在本浏览器示例空间</div><div id="message" hidden></div>'+sections+'<div id="state-feedback"></div><div class="voice-strip" aria-live="polite">语音提示：<span id="spoken">尚未开始</span></div><nav class="navigation" id="navigation" aria-label="主导航"></nav></div>'
review='''<aside class="review"><span class="label">Human 2 · 方向 A</span><h2>亲手试一遍自己的节奏</h2><p>从今日自由选择L1–L6，查看“各级标准”；对照上次摸底和当前选择，点开始即首个收紧，无准备/试听前置。快速语音是“紧／松”。摸底可选。手机打开时，下方是独立的场景面板。</p><ul><li>示例与个人记录隔离，可随时重置。</li><li>语音由浏览器系统语音演示；通知、来电、锁屏为交互模拟，不证明 Android 后台能力。</li><li>当前运行验证待完成，请勿把快速演示节奏用于实际跟练。</li></ul><small id="review-current"></small><p id="review-count"></p><p id="review-preview" hidden>正在查看状态样例，不能作为真实执行证据。</p><section><h3>可清除的示例</h3><div class="twocol"><button class="secondary" data-review-action="seed" data-value="fresh">清空示例，无等级起练</button><button class="secondary" data-review-action="seed" data-value="level">载入 L3 示例</button><button class="secondary" data-review-action="seed" data-value="six">连续6日，试恢复日</button><button class="secondary" data-review-action="seed" data-value="fourteen">14日，试一次提示</button><button class="secondary" data-review-action="seed" data-value="quota">当日40次，试上限</button></div></section><section><h3>演示时钟与语音</h3><div class="twocol"><button class="secondary" data-review-action="speed" data-value="1">真实秒数</button><button class="secondary" data-review-action="speed" data-value="20">20倍流程快进</button></div><p id="speed-note">真实秒数；仅演示，按身体感受停止。</p><button class="secondary" data-review-action="caption">切换系统语音 / 仅模拟提示</button><p id="caption-note">系统语音演示（需设备支持）</p></section><section><h3>失败与返回</h3><button class="secondary" data-review-action="rules-fault">模拟规则配置损坏，试手动继续</button><button class="secondary" data-review-action="fault">让下一次产品操作读写失败</button><p id="fault-note">默认不注入失败。</p><button class="secondary" data-review-action="focus-return">模拟通话结束 / 焦点返回</button><button class="secondary" data-interaction-id="INT-35">模拟进程终止后重开</button></section><section><h3>契约状态检查</h3><select id="inspectState" aria-label="选择契约状态"></select><button class="secondary" data-review-action="inspect-state">查看该状态样例</button><small>样例展示不算 runtime 证据；只有真实点击路径、console 与截图复核才能通过运行 gate。</small><button class="secondary" data-review-action="export">导出本页操作日志</button></section></aside>'''
(B/'prototype.html').write_text(head+body+review+'</main>'+states+controls+'<script>'+js.replace('</script','<\\/script')+'</script></body></html>')
# 明确只读快照；不改上游事实。
for n in ['UX_CONTRACT.json','DIRECTION_SET.json']:(B/n).write_bytes((D/n).read_bytes())
manifest={'prototype_version':'PROTOTYPE-V4.0','selected_direction':'A','status':'PENDING_RUNTIME_VALIDATION','formal_input_status':'VALID','static_integrity':'READY','ux_contract':{'path':'../UX_CONTRACT.json','snapshot_path':'UX_CONTRACT.json','sha256':bindings['ux_contract_sha256'],'version':U['ux_contract_version']},'direction_set':{'path':'../DIRECTION_SET.json','snapshot_path':'DIRECTION_SET.json','sha256':bindings['direction_set_sha256'],'version':DIR['direction_version'],'selected_direction':'A','approval_ref':U['selected_direction']['approval_ref'],'approval_evidence':DIR['selection_evidence']},'prototype':{'path':'prototype.html','sha256':sha(B/'prototype.html'),'self_contained':True},'asset_delivery':{'status':'EMPTY_EXPLICIT','reason':'HTML/CSS/JS与状态/控制模板全部内联；无远程字体、图片、脚本或音频资产。系统语音使用浏览器能力。'},'screens':[x['screen_id'] for x in U['screens']],'interactions':[x['interaction_id'] for x in U['interactions']],'states':[x['state_id'] for x in U['states']],'interaction_bindings':[{'interaction_id':x['interaction_id'],'screen_id':x['screen_id'],'control_template':'control-'+x['interaction_id'],'handler':'act','automatic':x['interaction_id'] in ['INT-09','INT-16','INT-17','INT-18','INT-25','INT-31','INT-60']} for x in U['interactions']],'state_bindings':[{'state_id':x['state_id'],'screen_id':x['screen_id'],'kind':x['kind'],'template':'state-'+x['state_id'],'switch_handler':'go','screenshot_status':'NOT_CAPTURED'} for x in U['states']],'five_slots':{'prototype_html':'prototype.html','assets':'EMPTY_EXPLICIT','manifest':'PROTOTYPE_MANIFEST.json','screenshot_index':'PROTOTYPE_SCREENSHOT_INDEX.md','qa':'PROTOTYPE_QA.md'},'runtime_validation':{'status':'PENDING','browser_executed':False,'console_inspected':False,'console_blocking_errors':None,'page_errors':None,'evidence_refs':['runtime-evidence/runtime-attempt.json'],'required_interactions':[i['interaction_id'] for i in U['interactions']],'required_states':[s['state_id'] for s in U['states']],'required_screenshot_states':[s['state_id'] for s in U['states']]},'changes':{'version':'V4','feedback_ref':'PROTOTYPE_V4-变更说明.md','applied':['V4_ZERO_PRECONDITION_START'],'prior_human2_approval':False},'human_approval':{'status':'NEEDS_REVISION_REVIEW','approved':False,'evidence':None},'technology_reuse':[{'decision':'REUSE','capability':'可点击移动界面与本地模拟记录','candidate':'原生HTML/CSS、DOM、Web Storage','reason':'本次按用户指定做自包含HTML模拟器，无需依赖、框架或旧项目代码。'},{'decision':'REUSE','capability':'演示语音','candidate':'浏览器系统SpeechSynthesis','reason':'复用平台语音能力；不冒充Android原生音频证明。'},{'decision':'ADAPT','capability':'契约规则、阶段推进、模拟场景','candidate':'原生事件/计时的受控业务映射','reason':'绑定已批准规则与同一阶段状态，单主Level/日额度/原相位恢复。'},{'decision':'REVIEW_FOR_REUSE','capability':'旧项目/技术样机','status':'NOT_REUSED','reason':'未审查，不读取或搬用技术样机。正式Reuse Audit仍在用户Prototype Approval后、SDD前。'},{'decision':'BUILD','capability':'底层播放/界面框架','status':'NOT_SELECTED','reason':'原生能力足够，不自建引擎或引入未审组件。'}],'limitations':['HTML不验证Android耳机/媒体焦点/通知/锁屏后台服务；对应操作为明确可点击模拟。','20倍快进只看流程，不是训练节奏；状态样例不算运行执行证据。','本页导出的是自报操作日志，须真实浏览器console/截图复核后才能形成QA PASS。']}
(B/'PROTOTYPE_MANIFEST.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
